import openpyxl
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
wsd=wb['Data']
print('Data cells containing years/headers/non-empty all rows cols A:L:')
for r in range(1, wsd.max_row+1):
    entries=[]
    for c in range(1, min(wsd.max_column,12)+1):
        v=wsd.cell(r,c).value
        if v is not None:
            entries.append(f"{wsd.cell(r,c).coordinate}={v!r}")
    if entries:
        print(r, '; '.join(entries))
print('Cells equal 2018-2022:')
for row in wsd.iter_rows():
    for cell in row:
        if cell.value in [2018,2019,2020,2021,2022,'2018','2019','2020','2021','2022']:
            print(cell.coordinate, repr(cell.value))
print('Hidden rows/cols around 1-38?')
print('hidden rows:', [i for i,d in wsd.row_dimensions.items() if d.hidden])
print('hidden cols:', [i for i,d in wsd.column_dimensions.items() if d.hidden])
